struct Reicon: View {
    let name: ReiconName
    var size: CGFloat = 15

    var body: some View {
        Canvas { ctx, canvasSize in
            let scale = min(canvasSize.width, canvasSize.height) / 24.0
            for d in name.svgPaths {
                var path = SVGPathParser.parse(d)
                path = path.applying(CGAffineTransform(scaleX: scale, y: scale))
                ctx.fill(path, with: .foreground, style: FillStyle(eoFill: true))
            }
        }
        .frame(width: size, height: size)
    }
}

private enum SVGPathParser {
    static func parse(_ d: String) -> Path {
        var path = Path()
        let tokens = tokenize(d)
        var i = 0
        var cur = CGPoint.zero
        var start = CGPoint.zero
        var lastCtrl: CGPoint?
        var lastCmd: Character = " "

        func nextFloat() -> CGFloat {
            guard i < tokens.count, let v = Double(tokens[i]) else { return 0 }
            i += 1
            return CGFloat(v)
        }

        func isNumber(_ s: String) -> Bool {
            guard let first = s.first else { return false }
            return first.isNumber || first == "-" || first == "+" || first == "."
        }

        while i < tokens.count {
            let tok = tokens[i]
            let cmd: Character
            if tok.count == 1 && tok.first!.isLetter {
                cmd = tok.first!
                i += 1
            } else {
                cmd = (lastCmd == "M") ? "L" : (lastCmd == "m" ? "l" : lastCmd)
            }

            switch cmd {
            case "M":
                cur = CGPoint(x: nextFloat(), y: nextFloat())
                start = cur
                path.move(to: cur)
                lastCtrl = nil
            case "m":
                cur = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                start = cur
                path.move(to: cur)
                lastCtrl = nil
            case "L":
                cur = CGPoint(x: nextFloat(), y: nextFloat())
                path.addLine(to: cur)
                lastCtrl = nil
            case "l":
                cur = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                path.addLine(to: cur)
                lastCtrl = nil
            case "H":
                cur = CGPoint(x: nextFloat(), y: cur.y)
                path.addLine(to: cur)
                lastCtrl = nil
            case "h":
                cur = CGPoint(x: cur.x + nextFloat(), y: cur.y)
                path.addLine(to: cur)
                lastCtrl = nil
            case "V":
                cur = CGPoint(x: cur.x, y: nextFloat())
                path.addLine(to: cur)
                lastCtrl = nil
            case "v":
                cur = CGPoint(x: cur.x, y: cur.y + nextFloat())
                path.addLine(to: cur)
                lastCtrl = nil
            case "C":
                let c1 = CGPoint(x: nextFloat(), y: nextFloat())
                let c2 = CGPoint(x: nextFloat(), y: nextFloat())
                let end = CGPoint(x: nextFloat(), y: nextFloat())
                path.addCurve(to: end, control1: c1, control2: c2)
                lastCtrl = c2
                cur = end
            case "c":
                let c1 = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                let c2 = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                let end = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                path.addCurve(to: end, control1: c1, control2: c2)
                lastCtrl = c2
                cur = end
            case "S":
                let c1 = lastCtrl.map { CGPoint(x: 2 * cur.x - $0.x, y: 2 * cur.y - $0.y) } ?? cur
                let c2 = CGPoint(x: nextFloat(), y: nextFloat())
                let end = CGPoint(x: nextFloat(), y: nextFloat())
                path.addCurve(to: end, control1: c1, control2: c2)
                lastCtrl = c2
                cur = end
            case "s":
                let c1 = lastCtrl.map { CGPoint(x: 2 * cur.x - $0.x, y: 2 * cur.y - $0.y) } ?? cur
                let c2 = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                let end = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                path.addCurve(to: end, control1: c1, control2: c2)
                lastCtrl = c2
                cur = end
            case "Q":
                let c = CGPoint(x: nextFloat(), y: nextFloat())
                let end = CGPoint(x: nextFloat(), y: nextFloat())
                path.addQuadCurve(to: end, control: c)
                lastCtrl = c
                cur = end
            case "q":
                let c = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                let end = CGPoint(x: cur.x + nextFloat(), y: cur.y + nextFloat())
                path.addQuadCurve(to: end, control: c)
                lastCtrl = c
                cur = end
            case "Z", "z":
                path.closeSubpath()
                cur = start
                lastCtrl = nil
            default:
                if i < tokens.count && isNumber(tokens[i]) { i += 1 }
            }
            lastCmd = cmd
        }
        return path
    }

    private static func tokenize(_ d: String) -> [String] {
        var out: [String] = []
        var cur = ""
        for ch in d {
            if ch.isLetter && ch != "e" && ch != "E" {
                if !cur.isEmpty { out.append(cur); cur = "" }
                out.append(String(ch))
            } else if ch == " " || ch == "," || ch == "\n" || ch == "\t" {
                if !cur.isEmpty { out.append(cur); cur = "" }
            } else if (ch == "-" || ch == "+") && !cur.isEmpty && cur.last != "e" && cur.last != "E" {
                out.append(cur)
                cur = String(ch)
            } else {
                cur.append(ch)
            }
        }
        if !cur.isEmpty { out.append(cur) }
        return out
    }
}
